def bowling_score(rolls) -> int:
    if not isinstance(rolls, (list, tuple)):
        raise ValueError("rolls must be a list or tuple")

    def valid_roll(value):
        return isinstance(value, int) and not isinstance(value, bool) and 0 <= value <= 10

    if any(not valid_roll(roll) for roll in rolls):
        raise ValueError("invalid roll")

    index = 0

    # Validate and consume the first nine frames.
    for _ in range(9):
        if index >= len(rolls):
            raise ValueError("too few rolls")

        first = rolls[index]
        index += 1

        if first == 10:
            continue

        if index >= len(rolls):
            raise ValueError("too few rolls")

        second = rolls[index]
        index += 1

        if first + second > 10:
            raise ValueError("frame exceeds 10 pins")

    # Validate and consume the tenth frame and any bonus rolls.
    if index >= len(rolls):
        raise ValueError("too few rolls")

    first = rolls[index]
    index += 1

    if first == 10:
        if index + 1 >= len(rolls):
            raise ValueError("too few bonus rolls")

        bonus_one = rolls[index]
        bonus_two = rolls[index + 1]
        index += 2

        if bonus_one != 10 and bonus_one + bonus_two > 10:
            raise ValueError("bonus rolls exceed 10 pins")
    else:
        if index >= len(rolls):
            raise ValueError("too few rolls")

        second = rolls[index]
        index += 1

        if first + second > 10:
            raise ValueError("frame exceeds 10 pins")

        if first + second == 10:
            if index >= len(rolls):
                raise ValueError("too few bonus rolls")
            index += 1

    if index != len(rolls):
        raise ValueError("too many rolls")

    score = 0
    index = 0

    for _ in range(10):
        if rolls[index] == 10:
            score += 10 + rolls[index + 1] + rolls[index + 2]
            index += 1
        else:
            frame_total = rolls[index] + rolls[index + 1]
            if frame_total == 10:
                score += 10 + rolls[index + 2]
            else:
                score += frame_total
            index += 2

    return score
